tool_input.content:
/* R29 — Teste como usuário final (Doom Clone).
 * Navega, clica JOGAR, exercita WASD + giro Q/E + HUD + minimapa,
 * lê estado do jogo (window.__game/__engine), captura console errors e screenshots.
 * Uso: npx -y -p playwright node r29-user-test.mjs /usr/bin/chromium
 */
import { chromium } from 'playwright';

const EXEC = process.argv[2] || '/usr/bin/chromium';
const URL = 'http://127.0.0.1:8137/index.html';
const results = [];
const consoleErrors = [];

const browser = await chromium.launch({ executablePath: EXEC, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });

page.on('console', (msg) => {
  if (msg.type() === 'error') consoleErrors.push(msg.text());
});
page.on('pageerror', (err) => consoleErrors.push(`PAGEERROR: ${err.message}`));

try {
  await page.goto(URL, { waitUntil: 'load', timeout: 30000 });
  await page.waitForTimeout(2500);

  // 1. Menu visível
  const menuVisible = await page.locator('#menu').isVisible();
  results.push(['menu visível', menuVisible]);

  // 2. Canvas 3D existe e com pixels (não preto total)
  const canvasInfo = await page.evaluate(() => {
    const cv = document.querySelector('#game');
    const gl = cv.getContext('webgl2') || cv.getContext('webgl');
    let nonBlack = -1;
    try {
      const px = new Uint8Array(4);
      gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
      nonBlack = px[0] + px[1] + px[2];
    } catch (e) { nonBlack = -2; }
    return { w: cv.width, h: cv.height, cornerRGB: nonBlack };
  });
  results.push(['canvas w/h', `${canvasInfo.w}x${canvasInfo.h}`]);
  results.push(['canvas pixel não-preto (0=preto total)', canvasInfo.cornerRGB > 0]);

  await page.screenshot({ path: '/tmp/opencode/r29_menu.png' });

  // 3. Clicar JOGAR (pointer lock pode falhar no headless — teclas cobrem)
  await page.click('#start-btn');
  await page.waitForTimeout(800);
  const hudVisible = await page.locator('#hud').isVisible();
  results.push(['HUD visível após START', hudVisible]);

  // 4. Estado do jogo: câmera inicial + spawn
  const spawnState = await page.evaluate(() => {
    const e = window.__engine || (window.__game && window.__game.engine);
    const g = window.__game;
    if (!e || !e.camera) return { error: 'engine/camera ausente' };
    const p = e.camera.position;
    return {
      state: g && g.state ? g.state : 'unknown',
      cam: [p.x.toFixed(2), p.y.toFixed(2), p.z.toFixed(2)],
      yaw: e.camera.rotation.y.toFixed(2),
      health: g && g.player && g.player.state ? g.player.state.health : null,
    };
  });
  results.push(['estado/câmera inicial', JSON.stringify(spawnState)]);

  // 5. W por 1.2s → posição deve avançar em Z (ou X, conforme yaw leste)
  await page.keyboard.down('KeyW');
  await page.waitForTimeout(1200);
  await page.keyboard.up('KeyW');
  await page.waitForTimeout(200);
  const afterW = await page.evaluate(() => {
    const e = window.__engine; const p = e.camera.position;
    return [p.x.toFixed(2), p.y.toFixed(2), p.z.toFixed(2)];
  });
  results.push(['câmera após W 1.2s', afterW.join(',')]);
  results.push(['movimento W efetivo (>0 residuo)', JSON.stringify(afterW) !== JSON.stringify(spawnState.cam ?? null)]);

  // 6. D por 0.8s → strafe lateral
  await page.keyboard.down('KeyD');
  await page.waitForTimeout(800);
  await page.keyboard.up('KeyD');
  await page.waitForTimeout(150);
  const afterD = await page.evaluate(() => {
    const e = window.__engine; const p = e.camera.position;
    return [p.x.toFixed(2), p.y.toFixed(2), p.z.toFixed(2)];
  });
  results.push(['câmera após W+D', afterD.join(',')]);

  // 7. Giro Q + E (fallback sem pointer lock) altera yaw
  const yawBefore = await page.evaluate(() => window.__engine.camera.rotation.y);
  await page.keyboard.press('KeyQ');
  await page.waitForTimeout(300);
  const yawAfterQ = await page.evaluate(() => window.__engine.camera.rotation.y);
  results.push(['giro Q altera yaw', Math.abs(yawAfterQ - yawBefore) > 0.05]);

  // 8. HUD: VIDA 100, minimapa canvas, crosshair
  const hud = await page.evaluate(() => ({
    health: document.querySelector('#health-value')?.textContent,
    kills: document.querySelector('#kills-value')?.textContent,
    weapon: document.querySelector('#weapon-name')?.textContent,
    minimapCanvas: !!document.querySelector('#minimap canvas'),
    ammo: document.querySelector('#ammo-count')?.textContent,
  }));
  results.push(['HUD valores', JSON.stringify(hud)]);

  // 9. Disparo (mouse esq.) — sem erro, municiao pode consumir
  await page.mouse.click(640, 400);
  await page.waitForTimeout(200);
  results.push(['disparo sem pageerror', consoleErrors.length === 0]);

  await page.screenshot({ path: '/tmp/opencode/r29_playing.png' });

  // 10. Pausa/retorno (Esc não abre pointer-lock exit no headless; testa P)
  await page.keyboard.press('KeyP');
  await page.waitForTimeout(300);
  const pausedVisible = await page.locator('#paused').isVisible();
  results.push(['pause (P) mostra overlay', pausedVisible]);

  // 11. Minimapa desenhou pixels (não vazio)
  const mmPixels = await page.evaluate(() => {
    const cv = document.querySelector('#minimap canvas');
    if (!cv || !cv.width) return 0;
    const ctx = cv.getContext('2d');
    const d = ctx.getImageData(0, 0, cv.width, cv.height).data;
    let nz = 0;
    for (let i = 0; i < d.length; i += 4) if (d[i] + d[i + 1] + d[i + 2] > 24) nz++;
    return nz;
  });
  results.push(['minimapa com pixels não-vazios', mmPixels > 50]);
} catch (err) {
  results.push(['EXCEÇÃO no fluxo', err.message]);
  consoleErrors.push(`FLOW: ${err.message}`);
}

await browser.close();

console.log('\n===== RESULTADOS R29 =====');
for (const [k, v] of results) console.log(`${v === true ? '✅' : v === false ? '❌' : 'ℹ️'} ${k}: ${v}`);
console.log(`\nConsole errors (${consoleErrors.length}):`);
for (const e of consoleErrors.slice(0, 10)) console.log('  -', e);
const anyFail = results.some(([, v]) => v === false);
console.log(`\nVEREDITO: ${anyFail ? 'NAO_PASSOU (há falhas)' : 'PASSOU (sem falhas objetivas)'}`);

