cd /tmp/opencode && cat > gauntlet_capture.mjs << 'EOF'
import { firefox } from 'playwright';

const browser = await firefox.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });

// captura console/erros
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('requestfailed', r => errors.push('REQFAIL: ' + r.url()));

// 1. MENU
await page.goto('http://127.0.0.1:8137/', { waitUntil: 'networkidle' });
await page.waitForTimeout(800);
await page.screenshot({ path: '/tmp/opencode/gl_menu.png' });

// 2. START — clicar no botão
const clicked = await page.evaluate(() => {
  const btns = [...document.querySelectorAll('button')];
  const start = btns.find(b => /start|iniciar|jogar/i.test(b.textContent || ''));
  if (start) { start.click(); return true; }
  return false;
});
await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/opencode/gl_playing.png' });

// 3. info da página
const info = await page.evaluate(() => ({
  title: document.title,
  buttons: [...document.querySelectorAll('button')].map(b => b.textContent.trim()).slice(0, 5),
  canvas: !!document.querySelector('canvas'),
  fps: window.__fps || null,
}));

console.log('clicked start:', clicked);
console.log('info:', JSON.stringify(info));
console.log('erros:', errors.length ? errors.slice(0, 5) : 'nenhum');
await browser.close();
console.log('screenshots salvos: gl_menu.png, gl_playing.png');
EOF
timeout 90 node gauntlet_capture.mjs 2>&1 | head -20

