cd /tmp/opencode && cat > playtest.mjs << 'EOF'
import { firefox } from 'playwright';

const browser = await firefox.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));

await page.goto('http://127.0.0.1:8137/', { waitUntil: 'networkidle' });
await page.waitForTimeout(600);

// START
await page.evaluate(() => document.querySelector('#start-btn')?.click());
await page.waitForTimeout(1000);

const snap = async (name) => {
  await page.screenshot({ path: `/tmp/opencode/pt_${name}.png` });
  const state = await page.evaluate(() => {
    const g = window.__game || {};
    const en = (g.enemies || []).map(e => ({ type: e.type, hp: Math.round(e.hp||0), x: +(e.pos?.x??0).toFixed(1), z: +(e.pos?.z??0).toFixed(1) }));
    return {
      state: g.state,
      pos: g.player ? { x: +(g.player.x??0).toFixed(1), z: +(g.player.z??0).toFixed(1), yaw: +((g.player.yaw??0)).toFixed(2) } : null,
      health: g.player?.health, armor: g.player?.armor,
      weapon: g.player?.weapon, ammo: g.player?.ammo ? Object.fromEntries(Object.entries(g.player.ammo).slice(0,4)) : null,
      enemies: en.length, alive: en.filter(e=>e.hp>0).length,
      pickups: g.pickups ? g.pickups.length : null,
      kills: g.kills ?? g.events?.kills ?? null,
    };
  });
  return state;
};

const hold = (key, ms) => page.keyboard.down(key).then(() => new Promise(r => setTimeout(r, ms))).then(() => page.keyboard.up(key));
const turn = async (key, times=1) => { for (let i=0;i<times;i++){ await page.keyboard.press(key); await page.waitForTimeout(120);} };

// Tour 1: spawn (salão) — olhar ao redor
const s0 = await snap('spawn');
await turn('KeyQ', 8); await snap('spawn_giro');

// Tour 2: andar para frente (leste) até achar algo
await hold('KeyW', 2500); await snap('andar_leste');

// Tour 3: virar e andar (norte)
await turn('KeyE', 6); await hold('KeyW', 2500); await snap('andar_norte');

// Tour 4: explorar mais
await turn('KeyE', 6); await hold('KeyW', 2500); await snap('andar_oeste');

// Tour 5: trocar de arma e atirar (verificar armas)
await page.keyboard.press('Digit2'); await page.waitForTimeout(300);
await page.mouse.click(640, 360); await page.waitForTimeout(400);
await snap('arma2_tiro');
await page.keyboard.press('Digit3'); await page.waitForTimeout(300); await snap('arma3');
await page.keyboard.press('Digit4'); await page.waitForTimeout(300); await snap('arma4');
await page.keyboard.press('Digit1'); await page.waitForTimeout(300);

const final = await page.evaluate(() => {
  const g = window.__game || {};
  const en = (g.enemies || []).map(e => ({ type: e.type, hp: Math.round(e.hp||0) }));
  return { state: g.state, enemies: en, kills: g.kills ?? null,
    weapon: g.player?.weapon, weapons: g.player?.weapons || null,
    pickupsCount: g.pickups?.length ?? null };
});

console.log('=== SPAWN ==='); console.log(JSON.stringify(s0));
console.log('=== ANDAR LESTE ==='); console.log(JSON.stringify(s1 = await snap('x')));
console.log('=== FINAL ==='); console.log(JSON.stringify(final));
console.log('ERROS console:', errors.length ? errors.slice(0,5) : 'nenhum');
await browser.close();
console.log('screenshots: pt_spawn, pt_spawn_giro, pt_andar_leste, pt_andar_norte, pt_andar_oeste, pt_arma2_tiro, pt_arma3, pt_arma4');
EOF
