await page.waitForTimeout(600);
await page.evaluate(() => document.querySelector('#start-btn')?.click());
await page.waitForTimeout(1200);

const st = async () => page.evaluate(() => {
  const g = window.__game || {}; const p = g.player || {}; const w = g.weapons || {};
  const yaw = window.__engine?.camera?.rotation?.y ?? 0;
  return { x: +(p.pos?.x??0), z: +(p.pos?.z??0), yaw: +yaw.toFixed(3), hp: p.hp, armor: p.armor,
    weapon: w.current, owned: [...(w.owned||[])], ammo: { ...(w.ammo||{}) },
    alive: (g.enemies||[]).filter(e=>e.hp>0).length, kills: g.kills ?? 0 };
});
const hold = (key, ms) => page.keyboard.down(key).then(() => new Promise(r => setTimeout(r, ms))).then(() => page.keyboard.up(key));

const normalize = a => { while (a > Math.PI) a -= 2*Math.PI; while (a < -Math.PI) a += 2*Math.PI; return a; };

async function headingTo(tx, tz) {
  const s = await st();
  // direção do movimento W: mundo = moveVec(yaw, 0, -1): x = -sin(yaw)... ver move.js: ix=0, iz=-1 =>
  //   mundo.x = 0*cos + (-1)*sin(yaw) = -sin(yaw); mundo.z = -0*sin + (-1)*cos = -cos(yaw)
  // alvo: ângulo = atan2(tx-x, tz-z) na convenção z-entrando; yaw_alvo = atan2(-(tx-x), -(tz-z))
  const ang = Math.atan2(tx - s.x, tz - s.z);
  const yawTarget = -ang; // converte? testemos empiricamente: vira e vê se d diminui
  return normalize(yawTarget - s.yaw);
}

async function moveTo(tx, tz, label, maxSteps=120) {
  for (let i = 0; i < maxSteps; i++) {
    const s = await st();
    const d = Math.hypot(tx - s.x, tz - s.z);
    if (d < 0.5) { await page.waitForTimeout(250); return await st(); }
    const diff = await headingTo(tx, tz);
    if (Math.abs(diff) > 0.15) {
      const key = diff > 0 ? 'KeyQ' : 'KeyE';
      await page.keyboard.press(key); await page.waitForTimeout(80);
      continue;
    }
    await hold('KeyW', 300);
  }
  return await st();
}

