/* textures.js — texturas procedurais via Canvas 2D (zero assets externos).
 * Cada gerador devolve uma THREE.CanvasTexture em tons de CINZA (tint aplicado
 * pelo material.color da zona), com RepeatWrapping pronto para uso.
 * Exporta também helpers de cor (shade/tint) para materiais.
 */
import * as THREE from 'three';

const SIZE = 128;

function mk(size = SIZE) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  return c;
}

function tex(cv, rx = 1, ry = 1) {
  const t = new THREE.CanvasTexture(cv);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(rx, ry);
  t.anisotropy = 4;
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/* rng determinístico por semente (mesma textura = mesma aparência) */
function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function noiseRect(g, x, y, w, h, base, rnd, amp = 18) {
  for (let py = y; py < y + h; py++) {
    for (let px = x; px < x + w; px++) {
      const n = base + Math.round((rnd() - 0.5) * amp);
      g.fillStyle = `rgb(${n},${n},${n})`;
      g.fillRect(px, py, 1, 1);
    }
  }
}

/* ---------- PAREDE: tijolo com argamassa (4 fileiras × 2, offset) ---------- */
export function brickTexture(seed = 7) {
  const cv = mk();
  const g = cv.getContext('2d');
  const rnd = rng(seed);
  g.fillStyle = '#3c3c3c'; g.fillRect(0, 0, SIZE, SIZE); // argamassa
  const bh = SIZE / 4, bw = SIZE / 2; // 32px × 64px
  for (let row = 0; row < 4; row++) {
    const off = row % 2 ? -bw / 2 : 0;
    for (let col = -1; col < 2; col++) {
      const bx = off + col * bw;
      const base = 96 + Math.round((rnd() - 0.5) * 26);
      noiseRect(g, bx + 2, row * bh + 2, bw - 4, bh - 4, base, rnd);
      // bevel superior (luz)
      g.fillStyle = `rgb(${Math.min(255, base + 30)},${Math.min(255, base + 30)},${Math.min(255, base + 30)})`;
      g.fillRect(bx + 2, row * bh + 2, bw - 4, 3);
      // bevel inferior (sombra)
      g.fillStyle = `rgb(${Math.max(0, base - 26)},${Math.max(0, base - 26)},${Math.max(0, base - 26)})`;
      g.fillRect(bx + 2, row * bh + bh - 5, bw - 4, 3);
    }
  }
  return tex(cv);
}

/* ---------- CHÃO: lajota de pedra 2×2 com junta ---------- */
export function floorTexture(seed = 11) {
  const cv = mk();
  const g = cv.getContext('2d');
  const rnd = rng(seed);
  g.fillStyle = '#282828'; g.fillRect(0, 0, SIZE, SIZE); // junta
  const ts = SIZE / 2; // 64px por lajota
  for (let ty = 0; ty < 2; ty++) {
    for (let tx = 0; tx < 2; tx++) {
      const x = tx * ts, y = ty * ts;
      const base = 88 + Math.round((rnd() - 0.5) * 22);
      noiseRect(g, x + 3, y + 3, ts - 6, ts - 6, base, rnd, 14);
      // manchas de pedra
      for (let m = 0; m < 5; m++) {
        const mx = x + 8 + rnd() * (ts - 16), my = y + 8 + rnd() * (ts - 16);
        g.fillStyle = `rgba(0,0,0,${0.08 + rnd() * 0.1})`;
        g.beginPath(); g.arc(mx, my, 3 + rnd() * 5, 0, Math.PI * 2); g.fill();
      }
      g.fillStyle = `rgb(${Math.min(255, base + 26)},${Math.min(255, base + 26)},${Math.min(255, base + 26)})`;
      g.fillRect(x + 3, y + 3, ts - 6, 2);
      g.fillStyle = `rgb(${Math.max(0, base - 22)},${Math.max(0, base - 22)},${Math.max(0, base - 22)})`;
      g.fillRect(x + 3, y + ts - 5, ts - 6, 2);
    }
  }
  return tex(cv);
}

/* ---------- TETO: painéis com viga ---------- */
export function ceilingTexture(seed = 19) {
  const cv = mk();
  const g = cv.getContext('2d');
  const rnd = rng(seed);
  g.fillStyle = '#2c2c38'; g.fillRect(0, 0, SIZE, SIZE);
  g.fillStyle = '#3a3a46'; g.fillRect(0, 0, SIZE, 8);   // viga
  g.fillStyle = '#26262f'; g.fillRect(0, SIZE - 8, SIZE, 8);
  for (let i = 0; i < 3; i++) {
    const y = 16 + i * 36;
    g.fillStyle = '#33333e'; g.fillRect(0, y, SIZE, 4);
    g.fillStyle = `rgba(0,0,0,${0.2 + rnd() * 0.15})`;
    g.fillRect(0, y + 4, SIZE, 2);
  }
  noiseRect(g, 0, 10, SIZE, 4, 52, rnd, 8);
  return tex(cv);
}

/* ---------- METAL (portas) ---------- */
export function metalTexture(seed = 23) {
  const cv = mk();
  const g = cv.getContext('2d');
  const rnd = rng(seed);
  g.fillStyle = '#5c5c5c'; g.fillRect(0, 0, SIZE, SIZE);
  // riscos verticais de metal escovado
  for (let i = 0; i < 40; i++) {
    const x = rnd() * SIZE;
    const w = 1 + rnd() * 2;
    g.fillStyle = `rgba(255,255,255,${0.03 + rnd() * 0.05})`;
    g.fillRect(x, 0, w, SIZE);
  }
  // rebites
  for (let i = 0; i < 8; i++) {
    const x = 12 + rnd() * (SIZE - 24), y = 12 + rnd() * (SIZE - 24);
    g.fillStyle = '#8a8a8a';
    g.beginPath(); g.arc(x, y, 3, 0, Math.PI * 2); g.fill();
    g.fillStyle = '#3c3c3c';
    g.beginPath(); g.arc(x, y, 1.5, 0, Math.PI * 2); g.fill();
  }
  g.fillStyle = '#464646'; g.fillRect(0, 0, SIZE, 3);
  g.fillRect(0, SIZE - 3, SIZE, 3);
  return tex(cv);
}

/* ---------- LAVA ---------- */
export function lavaTexture(seed = 29) {
  const cv = mk();
  const g = cv.getContext('2d');
  const rnd = rng(seed);
  g.fillStyle = '#881100'; g.fillRect(0, 0, SIZE, SIZE);
  // veios claros
  for (let i = 0; i < 14; i++) {
    let x = rnd() * SIZE, y = rnd() * SIZE;
    const len = 20 + rnd() * 40;
    const ang = rnd() * Math.PI * 2;
    g.strokeStyle = `rgba(255,${120 + rnd() * 60},0,${0.5 + rnd() * 0.4})`;
    g.lineWidth = 1 + rnd() * 2.5;
    g.beginPath(); g.moveTo(x, y);
    for (let s = 0; s < len; s += 4) {
      x += Math.cos(ang + rnd() * 0.8) * 4;
      y += Math.sin(ang + rnd() * 0.8) * 4;
      g.lineTo(x, y);
    }
    g.stroke();
  }
  // bolhas escuras
  for (let i = 0; i < 6; i++) {
    g.fillStyle = `rgba(40,4,0,${0.4 + rnd() * 0.3})`;
    g.beginPath(); g.arc(rnd() * SIZE, rnd() * SIZE, 4 + rnd() * 7, 0, Math.PI * 2); g.fill();
  }
  return tex(cv);
}

/* ---------- PELE DE DEMÔNIO (mobs) ---------- */
export function fleshTexture(seed = 37) {
  const cv = mk();
  const g = cv.getContext('2d');
  const rnd = rng(seed);
  g.fillStyle = '#6a6a6a'; g.fillRect(0, 0, SIZE, SIZE);
  // veias
  for (let i = 0; i < 10; i++) {
    let x = rnd() * SIZE, y = rnd() * SIZE;
    const len = 16 + rnd() * 36;
    const ang = rnd() * Math.PI * 2;
    g.strokeStyle = `rgba(0,0,0,${0.25 + rnd() * 0.25})`;
    g.lineWidth = 1 + rnd() * 2;
    g.beginPath(); g.moveTo(x, y);
    for (let s = 0; s < len; s += 3) {
      x += Math.cos(ang + rnd() * 0.7) * 3;
      y += Math.sin(ang + rnd() * 0.7) * 3;
      g.lineTo(x, y);
    }
    g.stroke();
  }
  // manchas musculares
  for (let i = 0; i < 8; i++) {
    g.fillStyle = `rgba(0,0,0,${0.06 + rnd() * 0.08})`;
    g.beginPath(); g.ellipse(rnd() * SIZE, rnd() * SIZE, 8 + rnd() * 12, 5 + rnd() * 8, rnd() * Math.PI, 0, Math.PI * 2); g.fill();
  }
  return tex(cv);
}

/* ---------- PAINEL TECH (itens) ---------- */
export function techTexture(seed = 41) {
  const cv = mk();
  const g = cv.getContext('2d');
  const rnd = rng(seed);
  g.fillStyle = '#3a3a44'; g.fillRect(0, 0, SIZE, SIZE);
  g.fillStyle = '#2a2a33'; g.fillRect(6, 6, SIZE - 12, SIZE - 12);
  g.strokeStyle = '#5a5a6a';
  g.lineWidth = 2;
  g.strokeRect(6, 6, SIZE - 12, SIZE - 12);
  g.strokeStyle = `rgba(0,0,0,${0.5 + rnd() * 0.3})`;
  for (let i = 0; i < 5; i++) {
    const y = 16 + i * 20;
    g.beginPath(); g.moveTo(10, y); g.lineTo(SIZE - 10, y); g.stroke();
  }
  return tex(cv);
}

/* ---------- helpers de cor ---------- */
export function shade(hex, pct) {
  const n = parseInt(hex.replace('#', ''), 16);
  const r = Math.min(255, Math.max(0, ((n >> 16) & 255) + pct));
  const g = Math.min(255, Math.max(0, ((n >> 8) & 255) + pct));
  const b = Math.min(255, Math.max(0, (n & 255) + pct));
  return `rgb(${r},${g},${b})`;
}

/* textures.js — texturas procedurais via Canvas 2D (zero assets externos).
 * Cada gerador devolve uma THREE.CanvasTexture em tons de CINZA (tint aplicado
 * pelo material.color da zona), com RepeatWrapping pronto para uso.
 * Exporta também helpers de cor (shade/tint) para materiais.
 */
import * as THREE from 'three';

const SIZE = 128;

function mk(size = SIZE) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  return c;
}

function tex(cv, rx = 1, ry = 1) {
  const t = new THREE.CanvasTexture(cv);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(rx, ry);
  t.anisotropy = 4;
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/* rng determinístico por semente (mesma textura = mesma aparência) */
function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function noiseRect(g, x, y, w, h, base, rnd, amp = 18) {
  for (let py = y; py < y + h; py++) {
    for (let px = x; px < x + w; px++) {
      const n = base + Math.round((rnd() - 0.5) * amp);
      g.fillStyle = `rgb(${n},${n},${n})`;
      g.fillRect(px, py, 1, 1);
    }
  }
}

/* ---------- PAREDE: tijolo com argamassa (4 fileiras × 2, offset) ---------- */
export function brickTexture(seed = 7) {
  const cv = mk();
  const g = cv.getContext('2d');
  const rnd = rng(seed);
  g.fillStyle = '#3c3c3c'; g.fillRect(0, 0, SIZE, SIZE); // argamassa
  const bh = SIZE / 4, bw = SIZE / 2; // 32px × 64px
  for (let row = 0; row < 4; row++) {
    const off = row % 2 ? -bw / 2 : 0;
    for (let col = -1; col < 2; col++) {
      const bx = off + col * bw;
      const base = 96 + Math.round((rnd() - 0.5) * 26);
      noiseRect(g, bx + 2, row * bh + 2, bw - 4, bh - 4, base, rnd);
      // bevel superior (luz)
      g.fillStyle = `rgb(${Math.min(255, base + 30)},${Math.min(255, base + 30)},${Math.min(255, base + 30)})`;
      g.fillRect(bx + 2, row * bh + 2, bw - 4, 3);
      // bevel inferior (sombra)
      g.fillStyle = `rgb(${Math.max(0, base - 26)},${Math.max(0, base - 26)},${Math.max(0, base - 26)})`;
      g.fillRect(bx + 2, row * bh + bh - 5, bw - 4, 3);
    }
  }
  return tex(cv);
}

/* ---------- CHÃO: lajota de pedra 2×2 com junta ---------- */
export function floorTexture(seed = 11) {
  const cv = mk();
  const g = cv.getContext('2d');
  const rnd = rng(seed);
  g.fillStyle = '#282828'; g.fillRect(0, 0, SIZE, SIZE); // junta
  const ts = SIZE / 2; // 64px por lajota
  for (let ty = 0; ty < 2; ty++) {
    for (let tx = 0; tx < 2; tx++) {
      const x = tx * ts, y = ty * ts;
      const base = 88 + Math.round((rnd() - 0.5) * 22);
      noiseRect(g, x + 3, y + 3, ts - 6, ts - 6, base, rnd, 14);
      // manchas de pedra
      for (let m = 0; m < 5; m++) {
        const mx = x + 8 + rnd() * (ts - 16), my = y + 8 + rnd() * (ts - 16);
        g.fillStyle = `rgba(0,0,0,${0.08 + rnd() * 0.1})`;
        g.beginPath(); g.arc(mx, my, 3 + rnd() * 5, 0, Math.PI * 2); g.fill();
      }
      g.fillStyle = `rgb(${Math.min(255, base + 26)},${Math.min(255, base + 26)},${Math.min(255, base + 26)})`;
      g.fillRect(x + 3, y + 3, ts - 6, 2);
      g.fillStyle = `rgb(${Math.max(0, base - 22)},${Math.max(0, base - 22)},${Math.max(0, base - 22)})`;
      g.fillRect(x + 3, y + ts - 5, ts - 6, 2);
    }
  }
  return tex(cv);
}

/* ---------- TETO: painéis com viga ---------- */
export function ceilingTexture(seed = 19) {
  const cv = mk();
  const g = cv.getContext('2d');
  const rnd = rng(seed);
  g.fillStyle = '#2c2c38'; g.fillRect(0, 0, SIZE, SIZE);
  g.fillStyle = '#3a3a46'; g.fillRect(0, 0, SIZE, 8);   // viga
  g.fillStyle = '#26262f'; g.fillRect(0, SIZE - 8, SIZE, 8);
  for (let i = 0; i < 3; i++) {
    const y = 16 + i * 36;
    g.fillStyle = '#33333e'; g.fillRect(0, y, SIZE, 4);
    g.fillStyle = `rgba(0,0,0,${0.2 + rnd() * 0.15})`;
    g.fillRect(0, y + 4, SIZE, 2);
  }
  noiseRect(g, 0, 10, SIZE, 4, 52, rnd, 8);
  return tex(cv);
}

/* ---------- METAL (portas) ---------- */
export function metalTexture(seed = 23) {
  const cv = mk();
  const g = cv.getContext('2d');
  const rnd = rng(seed);
  g.fillStyle = '#5c5c5c'; g.fillRect(0, 0, SIZE, SIZE);
