    g.fillStyle = `rgba(255,255,255,${0.03 + rnd() * 0.05})`;
    g.fillRect(x, 0, w, SIZE);
  }
  // rebites
  for (let i = 0; i < 8; i++) {
    const x = 12 + rnd() * (SIZE - 24), y = 12 + rnd() * (SIZE - 24);
    g.fillStyle = '#8a8a8a';
    g.beginPath(); g.arc(x, y, 3, 0, Math.PI * 2); g.fill();
    g.fillStyle = '#3c3c3c';
    g.beginPath(); g.arc(x, y, 1.5, 0, Math.PI * 2); g.fill();
  }
  g.fillStyle = '#464646'; g.fillRect(0, 0, SIZE, 3);
  g.fillRect(0, SIZE - 3, SIZE, 3);
  return tex(cv);
}

/* ---------- LAVA ---------- */
export function lavaTexture(seed = 29) {
  const cv = mk();
  const g = cv.getContext('2d');
  const rnd = rng(seed);
