tool_input.content:
/* level.js — mapa em grade + builder Three.js. Zonas: entrada, salão, forja,
 * catacumbas, armadilha, arena. Símbolos:
 * # parede  . chão  P spawn jogador  D porta (E)  E saída (E)
 * H saúde  A armadura  m munição 2/3/4 armas  i imp  d demon  B baron  x secreto
 * ~ lava (dano)  L tocha
 */
import * as THREE from 'three';
import C from './constants.js';
import { brickTexture, floorTexture, ceilingTexture, metalTexture, lavaTexture, techTexture } from './textures.js';

const W = 44, H = 36;
const RAW = [
'############################################',
'#........#.........i#...........#........d.#',
'####.###.#..###..####..###.###..#..####..#.#',
'#..L..#.#..#2....#.....#.....#...#.....#...#',
'#..H..###..#.###.#..D..###.###.#..H...#...#',
'#.......P....L..#..i..#............#.......#',
'#..####..###..D..#######..#.#####.#..###..###',
'#.....#.....D.....i..#....#.....#.#........#',
'###.###..###..######.#..###.....#.########.#',
'#...#.L.......#....#.#....#..H..#........#.#',
'#..H.#..####..#.D..#..#####..##.#..#####....#',
'#....#..#..m..#....#..#....#....#..#....#d.##',
'#....D..#......#####..####..####..###..#####',
'#..###..#mmmm#.....#...........#......m..#.#',
'#.....#..####..##.###..#########..#####...#.#',
'#..H..D.....i..#.....#.....#.........H....#.#',
'####...#####..##.#####..###..#####....####.#',
'#...#Ad.....#....#....#.....#.....#..####..#',
'#...#####..###..#.#..#..m#..A.#..###.....#.#',
'#.......#.i..m..#.#.#....#....#..#......d#.#',
'#####..###.#####.##.#.###########.####....#.#',
'#...D.....3#..L..#..#............#....#####.#',
'#...##.####.#.#####.#.###.#####..#.##....#.#',
'#.........#.#.......#.#.......#..#.#..##..#.#',
'#.###########.#####.#.#####.#.###.#.######..#',
'#...#........#.....#d#.....#.....#.......#d.#',
'#...####..###..####.#..#####..##.#.#######.#',
'#...#......#.......#...#........#.....#.....#',
'#..#####..#####.###.#####..#######.#####..###',
'#..E..#L....4#.......#......#.....#........#',
'#####..##..####..####..###..###..######..####',
'#.........................#..............E...#',
'#..###..###..###..###..#####..##..####....#',
'#..#...B....B....B..L.B....#..#........H..x#',
'#..###..###..###..###..####..##..####....#',
'############################################',
];

export function buildLevel(engine) {
  // Normaliza: linhas para W via padEnd + fecha borda
  const rows = RAW.map((r) => r.padEnd(W, '#').slice(0, W).split(''));
  for (let c = 0; c < W; c++) { rows[0][c] = '#'; rows[H - 1][c] = '#'; }
  for (let r = 0; r < H; r++) { rows[r][0] = '#'; rows[r][W - 1] = '#'; }

  const { scene } = engine;
  const group = new THREE.Group();
  scene.add(group);

  /* Zonas por região (6): entrada, salao, forja, catacumbas, armadilha, arena */
  const zone = (r, c) => {
    if (r >= 28) return 'arena';
    if (r >= 24 && c >= 29) return 'armadilha';
    if (c >= 29) return 'catacumbas';
    if (c >= 18 && c < 29) return 'forja';
    if (c >= 8 && c < 18) return 'salao';
    return 'entrada';
  };
  const ZCOLOR = {
    entrada: 0x8a7a72, salao: 0x8c3a3a, forja: 0x8a5a38,
    catacumbas: 0x6a5848, armadilha: 0x98989e, arena: 0x4a4a6e,
  };
  const FCOLOR = {
    entrada: 0x7a746c, salao: 0x7a4040, forja: 0x6a4a30,
    catacumbas: 0x55463a, armadilha: 0x808086, arena: 0x48486a,
  };

  /* Texturas: uma por zona (tint via material.color sobre textura em cinza) */
  const wallMat = {}; const floorMat = {};
  const brickTex = {}; const floorTex = {};
  for (const z in ZCOLOR) {
    brickTex[z] = brickTexture(z.length * 11 + 3);
    floorTex[z] = floorTexture(z.length * 13 + 5);
    wallMat[z] = new THREE.MeshStandardMaterial({ map: brickTex[z], color: ZCOLOR[z], roughness: 0.92, metalness: 0.05 });
    floorMat[z] = new THREE.MeshStandardMaterial({ map: floorTex[z], color: FCOLOR[z], roughness: 0.95, metalness: 0.02 });
  }
  const doorMat = new THREE.MeshStandardMaterial({ map: metalTexture(21), color: 0xcc8833, metalness: 0.5, roughness: 0.45 });
  const exitMat = new THREE.MeshStandardMaterial({ map: techTexture(29), color: 0x66cc88, emissive: 0x228833, emissiveIntensity: 0.7 });
  const lavaMat = new THREE.MeshStandardMaterial({ map: lavaTexture(31), color: 0xff7733, emissive: 0xff4400, emissiveIntensity: 0.9 });
  const techMat = new THREE.MeshStandardMaterial({ map: techTexture(37), color: 0x334466, emissive: 0x224466, emissiveIntensity: 0.45 });
  const box1 = new THREE.BoxGeometry(1, 1, 1);

  const cells = {};       // "r,c" -> { solid, door?, secret?, exit?, lava? }
  const doors = []; const secrets = []; const exits = [];
  const pickups = []; const enemies = [];
  let playerSpawn = { x: 1.5, z: 1.5 };
  const visited = Array.from({ length: H }, () => new Array(W).fill(false));

  const WALL_H = 3.2; // altura da parede (até o teto) — mata o "ver por cima"

  for (let r = 0; r < H; r++) for (let c = 0; c < W; c++) {
    const ch = rows[r][c];
    const key = `${r},${c}`;
    const x = c + 0.5, z = r + 0.5;
    const zc = zone(r, c);
    /* chão (sempre, menos parede sólida) — tile ESPESSO (0.24) p/ não sumir em ângulo raso */
    const floor = new THREE.Mesh(box1, floorMat[zc]);
    floor.scale.set(1.02, 0.24, 1.02); floor.position.set(x, -0.12, z);
    group.add(floor);

    if (ch === '#') {
      const wall = new THREE.Mesh(box1, wallMat[zc]);
      wall.scale.set(1, WALL_H, 1);
      wall.position.set(x, WALL_H / 2, z);
      group.add(wall);
      cells[key] = { solid: true };
    } else if (ch === 'D') {
      const d = new THREE.Mesh(box1, doorMat);
      d.position.set(x, 1.2, z); d.scale.set(0.92, 2.4, 0.92);
      group.add(d);
      const door = { mesh: d, open: false, t: 1, r, c };
      doors.push(door);
      cells[key] = { solid: true, door };
    } else if (ch === 'E') {
      const e = new THREE.Mesh(box1, exitMat);
      e.position.set(x, 0.6, z); e.scale.set(0.5, 1.1, 0.5);
      group.add(e);
      exits.push({ r, c, mesh: e });
      cells[key] = { solid: false, exit: true };
    } else if (ch === 'x') {
      const s = new THREE.Mesh(box1, wallMat[zc]);
      s.scale.set(1, WALL_H, 1);
      s.position.set(x, WALL_H / 2, z);
      group.add(s);
      const sec = { mesh: s, open: false, r, c, secret: true };
      secrets.push(sec);
      cells[key] = { solid: true, secret: sec };
    } else if (ch === '~') {
      const l = new THREE.Mesh(box1, lavaMat);
      l.position.set(x, 0.02, z); l.scale.set(0.96, 0.1, 0.96);
      group.add(l);
      cells[key] = { solid: false, lava: true };
    } else if ('HAm234'.includes(ch)) {
      const p = makePickupMesh(ch);
      p.position.set(x, 0.55, z);
      group.add(p);
      const type = ch === 'H' ? 'health' : ch === 'A' ? 'armor' : ch === 'm' ? 'ammo' : ch === '2' ? 'shotgun' : ch === '3' ? 'chaingun' : 'rocket';
      pickups.push({ type, r, c, mesh: p, taken: false, x, z });
      cells[key] = { solid: false };
    } else if (ch === 'i' || ch === 'd' || ch === 'B') {
      enemies.push({ type: ch === 'i' ? 'imp' : ch === 'd' ? 'demon' : 'baron', r, c, x, z });
      cells[key] = { solid: false };
    } else if (ch === 'P') {
      playerSpawn = { x, z };
      cells[key] = { solid: false };
    } else if (ch === 'L') {
      cells[key] = { solid: false };
    } else {
      cells[key] = { solid: false };
    }
  }

  /* Iluminação: hemisférica forte (chão/paredes visíveis) + direcional (contraste) + tochas (L) como PointLights */
  const hemi = new THREE.HemisphereLight(0xc0d0ee, 0x667788, 2.0);
  scene.add(hemi);
  const ambient = new THREE.AmbientLight(0x707090, 0.7);
  scene.add(ambient);
  const dir = new THREE.DirectionalLight(0xffeedd, 1.5);
  dir.position.set(5, 12, 8);
  scene.add(dir);
  const torches = [];
  for (let r = 0; r < H; r++) for (let c = 0; c < W; c++) {
    if (rows[r][c] === 'L') {
      const light = new THREE.PointLight(0xffaa55, 2.8, 18, 1.4);
      light.position.set(c + 0.5, 2.2, r + 0.5);
      scene.add(light);
      /* chama: cone laranja + núcleo amarelo + glow (2 esferas) */
      const flame = new THREE.Group();
      const cone = new THREE.Mesh(
        new THREE.ConeGeometry(0.11, 0.34, 7),
        new THREE.MeshBasicMaterial({ color: 0xff8833 })
      );
      cone.position.y = 0.42;
      const core = new THREE.Mesh(
        new THREE.SphereGeometry(0.07, 6, 5),
        new THREE.MeshBasicMaterial({ color: 0xffdd66 })
      );
      core.position.y = 0.28;
      const glow = new THREE.Mesh(
        new THREE.SphereGeometry(0.22, 8, 6),
        new THREE.MeshBasicMaterial({ color: 0xff7722, transparent: true, opacity: 0.28 })
      );
      glow.position.y = 0.32;
      flame.add(cone, core, glow);
      flame.position.set(c + 0.5, 1.7, r + 0.5);
      group.add(flame);
      torches.push({ light, flame });
    }
  }
  /* frasco de tocha na parede */
  for (const t of torches) {
    const mount = new THREE.Mesh(
      new THREE.CylinderGeometry(0.05, 0.07, 0.2, 6),
      new THREE.MeshStandardMaterial({ color: 0x554433, roughness: 0.8 })
    );
    mount.position.copy(t.flame.position); mount.position.y = 1.42;
    group.add(mount);
  }

  /* Teto único (visão interna) — material iluminável p/ não virar buraco escuro */
  const ceil = new THREE.Mesh(
    new THREE.PlaneGeometry(W, H),
    new THREE.MeshLambertMaterial({ map: ceilingTexture(13), color: 0x8a8aa8, side: THREE.BackSide })
  );
  ceil.rotation.x = -Math.PI / 2; ceil.position.set(W / 2, WALL_H, H / 2);
  scene.add(ceil);

  const isSolid = (r, c) => {
    if (r < 0 || c < 0 || r >= H || c >= W) return true;
    const cell = cells[`${r},${c}`];
    if (!cell) return false;
    if (cell.door && cell.door.open) return false; // porta aberta = passável
    if (cell.secret && cell.secret.open) return false;
    return cell.solid;
  };
  const visit = (r, c) => { if (r >= 0 && c >= 0 && r < H && c < W) visited[r][c] = true; };

  const level = {
    W, H, rows, cells, doors, secrets, exits, pickups, enemies,
    playerSpawn, visited, torches,
    isSolid, visit,
    playerPos: null,
    openDoor(door) { if (!door.open) { door.open = true; door.t = 0; door.mesh.material = new THREE.MeshStandardMaterial({ color: 0x664422, transparent: true, opacity: 0.35 }); } },
    openSecret(sec) { if (!sec.open) { sec.open = true; sec.mesh.visible = false; } },
    update(dt) {
      /* anima portas abrindo */
      for (const d of doors) if (d.open && d.t < 1) { d.t = Math.min(1, d.t + dt * C.LEVEL.doorSpeed); d.mesh.position.y = 1.2 - d.t * 1.9; }
      /* tochas: luz oscila + chama tremula */
      const t = performance.now() * 0.001;
      for (const tor of torches) {
        tor.light.intensity = 1.2 + Math.sin(t * 9 + tor.light.position.x * 7) * 0.35;
        const s = 1 + Math.sin(t * 11 + tor.light.position.z * 5) * 0.18;
        tor.flame.scale.set(s, s, s);
      }
      /* pickups: giram e flutuam */
      const ft = performance.now() * 0.001;
      for (const pk of pickups) {
        if (pk.taken) continue;
        pk.mesh.rotation.y += dt * 1.6;
        pk.mesh.position.y = 0.55 + Math.sin(ft * 2.2 + pk.x * 3) * 0.08;
      }
    },
  };
  return level;
}

/* Pickups com forma rica por tipo (nada de cubo genérico) */
function makePickupMesh(ch) {
  const colors = { H: 0xff3333, A: 0x4488ff, m: 0xffcc33, '2': 0xcc8844, '3': 0x44cc88, '4': 0xcc4444 };
  const emissive = colors[ch];
  const base = new THREE.MeshStandardMaterial({ color: colors[ch], emissive, emissiveIntensity: 0.7, roughness: 0.4 });
  const g = new THREE.Group();
  let core;
  switch (ch) {
    case 'H': core = new THREE.Mesh(new THREE.OctahedronGeometry(0.22), base); break;
    case 'A': core = new THREE.Mesh(new THREE.IcosahedronGeometry(0.24), base); break;
    case 'm': core = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.2, 0.22), base); break;
    case '2': core = new THREE.Mesh(new THREE.BoxGeometry(0.52, 0.1, 0.16), base); break;
    case '3': core = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.5, 8), base); break;
    case '4': core = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 0.42, 8), base); break;
  }
  g.add(core);
  /* brilho suave em volta */
  const glow = new THREE.Mesh(
    new THREE.SphereGeometry(0.34, 8, 6),
    new THREE.MeshBasicMaterial({ color: emissive, transparent: true, opacity: 0.16 })
  );
  g.add(glow);
  return g;
}

/* Registrar como módulo — init constrói o nível na ordem correta (antes do player) */
let built = null;
window.__registerMod('level', {
  init(game, engine) {
    if (!built) { built = buildLevel(engine); game.level = built; }
  },
  update(dt, game) { if (built) built.update(dt); },
});

/* level.js — mapa em grade + builder Three.js. Zonas: entrada, salão, forja,
