import { fleshTexture } from './textures.js';

const AGGRO = 16;
const projGeo = new THREE.SphereGeometry(0.16, 8, 6);
const eyeMat = new THREE.MeshBasicMaterial({ color: 0xff3300 });

const MESH_CFG = {
