function makeEnemyMesh(type, scaleMul) {
  const cfg = C.ENEMIES[type];
  const m = MESH_CFG[type];
  const s = m.scale * scaleMul;
  const skinTex = fleshTexture(type.length * 17 + 7);
  const skinMat = new THREE.MeshStandardMaterial({ map: skinTex, color: cfg.color, roughness: 0.75 });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x332211, roughness: 0.9 });

  const g = new THREE.Group();

  /* pernas */
  for (const lx of [-m.legX, m.legX]) {
    const leg = new THREE.Mesh(new THREE.BoxGeometry(m.legs[0], m.legs[1], m.legs[2]), darkMat);
    leg.position.set(lx * s, m.legY * s, 0);
    g.add(leg);
  }
  /* torso */
  const torso = new THREE.Mesh(new THREE.BoxGeometry(m.torso[0], m.torso[1], m.torso[2]), skinMat);
  torso.position.y = m.torsoY * s;
  g.add(torso);
  /* braços */
  for (const ax of [-m.armX, m.armX]) {
    const arm = new THREE.Mesh(new THREE.BoxGeometry(m.arms[0], m.arms[1], m.arms[2]), skinMat);
    arm.position.set(ax * s, m.armY * s, 0);
    arm.rotation.z = ax > 0 ? -0.12 : 0.12;
    g.add(arm);
  }
  /* cabeça */
  const head = new THREE.Mesh(new THREE.BoxGeometry(m.head[0], m.head[1], m.head[2]), skinMat);
  head.position.y = m.headY * s;
  g.add(head);
  /* chifres (imp/baron/demon) — cones na testa */
  const hornMat = new THREE.MeshStandardMaterial({ color: 0xddccaa, roughness: 0.5 });
  for (const hx of [-0.5, 0.5]) {
    const horn = new THREE.Mesh(new THREE.ConeGeometry(m.horns, m.horns * 2.4, 5), hornMat);
    horn.position.set(hx * m.head[0] * 0.55 * s, m.hornY * s, 0);
    horn.rotation.z = hx > 0 ? m.hornAng : -m.hornAng;
    g.add(horn);
  }
  /* olhos emissivos grandes (visíveis na penumbra) */
  for (const ex of [-m.eyeX, m.eyeX]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(m.eyeR, 8, 6), eyeMat);
    eye.position.set(ex * s, m.eyeY * s, m.head[2] * 0.55 * s);
    g.add(eye);
  }
  /* nariz/boca em V (imp/baron) — 2 cones pequenos na face */
  const mouthMat = new THREE.MeshStandardMaterial({ color: 0x220000, emissive: 0x220000, emissiveIntensity: 0.4 });
  for (const fx of [-0.5, 0.5]) {
    const fang = new THREE.Mesh(new THREE.ConeGeometry(0.03 * s + 0.01, 0.1 * s, 4), mouthMat);
    fang.position.set(fx * m.head[0] * 0.35 * s, (m.headY - m.head[1] * 0.32) * s, m.head[2] * 0.55 * s);
    g.add(fang);
  }

  g.scale.setScalar(s > 0 ? 1 : 1); // escala já embutida nas medidas; grupos 1:1
  return g;
}

let spawned = false;
const projectiles = [];

function spawnProjectile(scene, from, to, cfg) {
  const p = new THREE.Mesh(projGeo, new THREE.MeshStandardMaterial({ color: 0xffaa33, emissive: 0xff8800, emissiveIntensity: 1.2 }));
  p.position.copy(from);
  const dir = to.clone().sub(from);
  dir.y = 0;
  if (dir.lengthSq() < 0.01) return;
  dir.normalize();
  p.userData.vel = dir.multiplyScalar(cfg.projSpeed);
  p.userData.dmg = cfg.damage;
  p.userData.life = 6;
  scene.add(p);
  projectiles.push(p);
}

window.__registerMod('enemies', {
  update(dt, game, engine) {
    const lvl = game.level;
    if (!lvl || !game.player) return;

    /* spawn único na primeira atualização */
    if (!spawned) {
      for (const s of lvl.enemies) {
        const cfg = C.ENEMIES[s.type];
        const mesh = makeEnemyMesh(s.type, 1);
        mesh.position.set(s.x, 0, s.z);
        engine.scene.add(mesh);
        game.enemies.push({
          type: s.type, mesh, pos: mesh.position, hp: cfg.hp,
          cooldown: Math.random() * 1,
          bob: Math.random() * Math.PI * 2,
          takeDamage(dmg) {
            this.hp -= dmg;
            game.events.onHit?.(this, dmg);
            if (this.hp <= 0) {
              this.dead = true;
              mesh.visible = false;
              game.stats.kills++;
              game.events.onKill?.(this);
            }
          },
        });
      }
      spawned = true;
    }

    const player = game.player;
    const pPos = player.pos;
    const now = performance.now() * 0.001;

    for (const e of game.enemies) {
      if (e.dead) continue;
      const cfg = C.ENEMIES[e.type];
      const dx = pPos.x - e.pos.x;
      const dz = pPos.z - e.pos.z;
      const dist = Math.hypot(dx, dz);
      e.cooldown -= dt;

      /* animação: bob de vida + tremor ao andar */
      const moving = cfg.attackType !== 'melee' ? (dist > (cfg.rangeMax || 14)) : (dist > cfg.meleeRange * 0.9);
      const bobAmp = moving ? 0.06 : 0.015;
      e.bob += dt * (moving ? 9 : 4);
      e.mesh.position.y = Math.abs(Math.sin(e.bob)) * bobAmp;

      if (dist < AGGRO) {
        const nx = dx / (dist || 1);
        const nz = dz / (dist || 1);

        if (cfg.attackType === 'melee') {
          if (dist > cfg.meleeRange * 0.9) {
            tryMove(e.pos, nx, nz, cfg.speed * dt, lvl);
          } else if (e.cooldown <= 0) {
            e.cooldown = cfg.cooldown;
            game.damagePlayer(cfg.damage, e.type);
            game.events.onEnemyAttack?.(e);
          }
        } else {
          /* ranged: mantém distância na faixa [rangeMin, rangeMax] */
          if (dist > cfg.rangeMax) tryMove(e.pos, nx, nz, cfg.speed * dt, lvl);
          else if (dist < cfg.rangeMin) tryMove(e.pos, -nx, -nz, cfg.speed * dt, lvl);
          else if (e.cooldown <= 0) {
            e.cooldown = cfg.cooldown;
            spawnProjectile(engine.scene, e.pos.clone().add(new THREE.Vector3(0, 1.3, 0)), pPos.clone(), cfg);
          }
        }
        /* olha para o jogador */
        e.mesh.rotation.y = Math.atan2(dx, dz);
      }
    }

    /* projéteis inimigos */
    for (let i = projectiles.length - 1; i >= 0; i--) {
      const p = projectiles[i];
      p.userData.life -= dt;
      p.position.addScaledVector(p.userData.vel, dt);
      const cell = lvl.cells[`${Math.floor(p.position.z)},${Math.floor(p.position.x)}`];
      const hitWall = cell && cell.solid;
      const hitPlayer = p.position.distanceTo(pPos) < 0.7;
      if (hitWall || hitPlayer || p.userData.life <= 0) {
        if (hitPlayer) { game.damagePlayer(p.userData.dmg, 'inimigo'); game.events.onEnemyProjectileHit?.(p.position); }
        engine.scene.remove(p);
        projectiles.splice(i, 1);
      }
    }
  },
});

/* movimento com slide em sólidos */
function tryMove(pos, nx, nz, step, lvl) {
  const tx = pos.x + nx * step;
  const tz = pos.z + nz * step;
  if (!lvl.isSolid(Math.floor(tz), Math.floor(tx))) { pos.x = tx; pos.z = tz; return; }
  if (!lvl.isSolid(Math.floor(pos.z), Math.floor(tx))) { pos.x = tx; return; }
  if (!lvl.isSolid(Math.floor(tz), Math.floor(pos.x))) { pos.z = tz; }
}

