import { firefox } from 'playwright';
const browser = await firefox.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
await page.goto('http://127.0.0.1:8137/', { waitUntil: 'networkidle' });
await page.waitForTimeout(600);
await page.evaluate(() => document.querySelector('#start-btn')?.click());
await page.waitForTimeout(1500);

// Encontra inimigo com LOS livre e teleporta para célula vizinha com visão
const spot = await page.evaluate(() => {
  const g = window.__game; const lvl = g.level;
  const hasLOS = (x1,z1,x2,z2) => {
    const steps = Math.ceil(Math.hypot(x2-x1, z2-z1) * 4);
    for (let i=1; i<steps; i++) {
      const t = i/steps;
      const r = Math.floor(z1 + (z2-z1)*t), c = Math.floor(x1 + (x2-x1)*t);
      if (lvl.isSolid(r, c)) return false;
    }
    return true;
  };
  for (const e of g.enemies) {
    const ex = Math.round(e.pos.x), ez = Math.round(e.pos.z);
    // procura célula livre a 3 de distância numa direção com LOS
    for (const [dx,dz] of [[0,3],[0,-3],[3,0],[-3,0],[2,2],[-2,2],[2,-2],[-2,-2]]) {
      const px = ex + dx, pz = ez + dz;
      if (px<1||pz<1||px>42||pz>34) continue;
      if (lvl.isSolid(Math.floor(pz), Math.floor(px))) continue;
      if (hasLOS(px, pz, ex, ez)) {
        return { mx: ex, mz: ez, px, pz, type: e.type, hp: e.hp };
      }
    }
  }
  return null;
});
console.log('spot:', JSON.stringify(spot));
if (spot) {
  await page.evaluate((s) => {
    const p = window.__game.player, eng = window.__engine;
    p.pos.set(s.px+0.5, 1.7, s.pz+0.5); p.vel?.set(0,0,0);
    eng.camera.position.set(s.px+0.5, 1.7, s.pz+0.5);
    const yaw = Math.atan2(-(s.mx - s.px), -(s.mz - s.pz));
    eng.camera.rotation.set(0, yaw, 0);
  }, spot);
  await page.waitForTimeout(600);
  await page.screenshot({ path: '/tmp/opencode/tex_mob_los.png' });
  console.log('capturado tex_mob_los.png');
  // testa tiro real via fire direto
  const r = await page.evaluate(() => {
    const g = window.__game;
    g.cameraDirUpdate?.();
    const before = g.enemies.find(e => e.hp > 0).hp;
    for (let i=0;i<8;i++) g.weapons.fire();
    const target = g.enemies.filter(e => !e.dead);
    return { before, after: target.length ? target[0].hp : 'morto', kills: g.stats.kills, hits: g.stats.hits, shots: g.stats.shots };
  });
  console.log('combate:', JSON.stringify(r));
}
console.log('ERROS:', errors);
await browser.close();
EOF
