from PIL import Image
import numpy as np
v = np.asarray(Image.open('/tmp/opencode/diff_vivo.png').convert('RGB'), dtype=np.int16)
m = np.asarray(Image.open('/tmp/opencode/diff_morto.png').convert('RGB'), dtype=np.int16)
diff = np.abs(v - m).sum(axis=2)
mask = diff > 60
ys, xs = np.where(mask)
print('pixels diferentes (mobs):', mask.sum())
if mask.sum() > 100:
    print(f'mobs bbox: x[{xs.min()},{xs.max()}] y[{ys.min()},{ys.max()}] (área {(xs.max()-xs.min())*(ys.max()-ys.min())})')
# isolando: o que há de DIFERENTE na região (cor média do mob na imagem viva)
region = v[ys.min():ys.max()+1, xs.min():xs.max()+1] if mask.sum()>0 else None
if region is not None:
    print('cor média região mobs:', [round(float(region[...,i].mean()),0) for i in range(3)])
# salva máscara ampliada p/ inspeção
if mask.sum() > 0:
    out = np.zeros((*mask.shape, 3), dtype=np.uint8)
    out[mask] = [255, 0, 0]
    Image.fromarray(out).resize((1280,720)).save('/tmp/opencode/diff_mask.png')
    print('máscara salva: diff_mask.png')
