await page.goto('http://127.0.0.1:8137/', { waitUntil: 'networkidle' });
await page.waitForTimeout(600);
await page.evaluate(() => document.querySelector('#start-btn')?.click());
await page.waitForTimeout(1500);
const d1 = await page.evaluate(() => {
  const g = window.__game, eng = window.__engine;
  // isola imp, trava posição, jogador longe (sem aggro)
  for (const e of g.enemies) if (e !== g.enemies[0]) { e.dead = true; e.mesh.visible = false; }
  const e0 = g.enemies[0];
  e0.pos.set(10.5, 0, 8.5); e0.mesh.position.set(10.5, 0, 8.5);
  e0.mesh.rotation.y = Math.PI;
  g.player.pos.set(30, 1.7, 30); g.player.vel?.set(0,0,0);
  eng.camera.position.set(7.0, 1.7, 8.5);
  eng.camera.rotation.set(0, -Math.PI/2, 0);
  return {
    camPos: eng.camera.position.toArray().map(v=>+v.toFixed(2)),
    camRot: eng.camera.rotation.toArray().map(v=>+v.toFixed(2)),
    dir: eng.camera.getWorldDirection(new THREE.Vector3()).toArray().map(v=>+v.toFixed(2)),
    rendererIsEngine: !!eng.renderer,
    tris: eng.renderer?.info?.render?.triangles ?? -1,
    totalEnemies: g.enemies.length,
    wallsNaCelula: g.level ? 'lvl' : 'sem-lvl'
  };
});
// raycast câmera -> imp: o que bloqueia?
const d2 = await page.evaluate((camPos) => {
  const eng = window.__engine, g = window.__game;
  const e0 = g.enemies[0];
  const origin = new THREE.Vector3(...camPos);
  const target = e0.mesh.position.clone().add(new THREE.Vector3(0,0.9,0));
  const dir = target.clone().sub(origin).normalize();
  const ray = new THREE.Raycaster(origin, dir);
  const walls = eng.scene.children.filter(o => o.isMesh && o.userData?.wall);
  const hits = ray.intersectObjects(walls, true);
  return {
    distAlvo: +origin.distanceTo(target).toFixed(2),
    bloqueadoPor: hits.length ? hits[0].object.userData : null,
    distBloqueio: hits.length ? +hits[0].distance.toFixed(2) : null,
    distAlvoInt: +origin.distanceTo(target).toFixed(2)
  };
}, d1.camPos);
console.log('DIAG1:', JSON.stringify(d1));
console.log('DIAG2:', JSON.stringify(d2));
// morre o imp -> compara triângulos
const d3 = await page.evaluate(() => {
  const g = window.__game, eng = window.__engine;
  g.enemies[0].takeDamage(9999);
  return { tris: eng.renderer.info.render.triangles };
});
console.log('DIAG3 (morto):', JSON.stringify(d3));
const d4 = await page.evaluate(() => {
  const eng = window.__engine;
  // câmera vigiada pelo renderer?
  return { camEq: eng.renderer === window.__renderer ? 'renderer==__renderer' : '?', camAtiva: eng.renderer && eng.renderer.domElement === document.querySelector('canvas') };
});
console.log('DIAG4:', JSON.stringify(d4));
await browser.close();
EOF
